const express = require('express');
const { createClient } = require('@splitsoftware/splitio');
const { Buffer } = require('buffer');

const app = express();
app.use(express.json({ limit: '10mb' }));

// Split.io client initialization
const factory = createClient({
  core: {
    authorizationKey: process.env.SPLIT_API_KEY || 'localhost',
  },
  startup: { readyTimeout: 5 }
});
const splitClient = factory.client();

// Native addon for high-performance buffer processing
let nativeProcessor;
try {
  nativeProcessor = require('./native_processor.node');
} catch (e) {
  console.warn('Native processor unavailable, using JS fallback');
  nativeProcessor = null;
}

// Buffer pool for reuse - manages native heap allocations
class BufferPool {
  constructor(size) {
    this.pool = [];
    this.maxSize = size;
    this.allocated = new Map();
  }

  acquire(length) {
    if (nativeProcessor) {
      const handle = nativeProcessor.allocBuffer(length);
      this.allocated.set(handle.id, handle);
      return handle;
    }
    return { id: Date.now(), buf: Buffer.alloc(length), freed: false };
  }

  release(handle) {
    if (!handle) return;
    if (nativeProcessor) {
      nativeProcessor.freeBuffer(handle);
      // BUG: handle remains in allocated map, can be freed again
      this.allocated.delete(handle.id);
    } else {
      handle.freed = true;
    }
  }

  // Dangerous: processes and releases in one call
  processAndRelease(handle, data) {
    if (nativeProcessor) {
      nativeProcessor.processInPlace(handle, data);
      this.release(handle); // First free
    }
    return handle;
  }
}

const pool = new BufferPool(64);

// Image transformation endpoint
app.post('/api/v2/transform', async (req, res) => {
  const { imageData, operations, userId } = req.body;

  if (!imageData || !operations) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Check feature flag for v2 pipeline (uses native processor)
  const treatment = splitClient.getTreatment(
    userId || 'anonymous',
    'native-transform-pipeline'
  );

  if (treatment === 'on') {
    // V2 path: native processing with buffer pool
    const rawData = Buffer.from(imageData, 'base64');
    const handle = pool.acquire(rawData.length);

    try {
      for (const op of operations) {
        if (op.type === 'resize') {
          // processAndRelease frees the buffer
          pool.processAndRelease(handle, rawData);
        }
        if (op.type === 'compress') {
          // BUG: Double-free - handle was already freed in processAndRelease
          // but we call release again here
          pool.release(handle);
        }
      }

      res.json({ status: 'processed', pipeline: 'v2-native' });
    } catch (err) {
      pool.release(handle); // potential triple-free on error
      res.status(500).json({ error: 'Processing failed' });
    }
  } else {
    // V1 path: pure JavaScript, no native allocations
    const rawData = Buffer.from(imageData, 'base64');
    const result = rawData.toString('base64'); // safe no-op placeholder
    res.json({ status: 'processed', pipeline: 'v1-safe', data: result });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', nativeAvailable: !!nativeProcessor });
});

app.listen(process.env.PORT || 3000, () => {
  console.log('Transform service running');
});

module.exports = app;
